const expand = 'Customer($select=CompanyName),Shipper($select=CompanyName),Order_Details($select=UnitPrice,Quantity,Discount;$expand=Product($select=ProductName))';
const url = 'https://services.odata.org/V4/Northwind/Northwind.svc/Orders?$format=json&$select=OrderID,OrderDate,RequiredDate,ShippedDate,Freight,ShipCity,ShipCountry&$expand=' + encodeURIComponent(expand);
return [{ json: { url, hoje: '1998-05-06' } }];

const hoje = $('Monta consulta').first().json.hoje;
const paginas = $input.all();
const dia = v => v ? v.slice(0, 10) : null;
const pedidos = paginas.flatMap(p => p.json.value || []).map(o => {
  const itens = (o.Order_Details || []).map(d => ({ produto: d.Product.ProductName, quantidade: d.Quantity, preco: d.UnitPrice, desconto_pct: Math.round(d.Discount * 100), liquido: d.UnitPrice * d.Quantity * (1 - d.Discount) }));
  return { pedido: o.OrderID, cliente: o.Customer ? o.Customer.CompanyName : 'Sem cliente', transportadora: o.Shipper ? o.Shipper.CompanyName : 'Sem transportadora', data: dia(o.OrderDate), prometido: dia(o.RequiredDate), enviado: dia(o.ShippedDate), frete: o.Freight, destino: o.ShipCity + ', ' + o.ShipCountry, valor: itens.reduce((s, i) => s + i.liquido, 0), itens };
});
return [{ json: { hoje, paginas: paginas.length, pedidos } }];

const d = $('Normaliza pedidos').first().json;
const r2 = v => Math.round(v * 100) / 100;
const dias = (a, b) => Math.round((Date.parse(b) - Date.parse(a)) / 86400000);
const abertos = d.pedidos.filter(p => !p.enviado).map(p => ({ pedido: p.pedido, cliente: p.cliente, data: p.data, prometido: p.prometido, valor: p.valor, dias_de_atraso: Math.max(dias(p.prometido, d.hoje), 0), dias_para_vencer: Math.max(dias(d.hoje, p.prometido), 0) }));
if (!abertos.length) return JSON.stringify({ status: 'SEM_DADOS' });
const atrasados = abertos.filter(p => p.dias_de_atraso > 0);
const hoje = abertos.filter(p => p.prometido === d.hoje);
const proximos = abertos.filter(p => p.dias_para_vencer >= 1 && p.dias_para_vencer <= 7);
const base = query.somente_atrasados ? atrasados : abertos;
const limite = Math.min(Number(query.limite) || 10, 30);
const lista = [...base].sort((a, b) => a.prometido.localeCompare(b.prometido) || b.valor - a.valor).slice(0, limite).map(p => ({ ...p, valor: r2(p.valor) }));
const soma = x => r2(x.reduce((s, p) => s + p.valor, 0));
return JSON.stringify({ status: 'OK', data_referencia: d.hoje, em_aberto: abertos.length, valor_em_aberto: soma(abertos), atrasados: atrasados.length, valor_atrasado: soma(atrasados), vencem_hoje: hoje.length, valor_vence_hoje: soma(hoje), vencem_nos_proximos_7_dias_sem_contar_hoje: proximos.length, valor_vence_nos_proximos_7_dias: soma(proximos), listados: lista.length, pedidos: lista });

const d = $('Normaliza pedidos').first().json;
const inicio = query.inicio || '1996-01-01';
const fim = query.fim || d.hoje;
const enviados = d.pedidos.filter(p => p.enviado && p.data >= inicio && p.data <= fim);
if (!enviados.length) return JSON.stringify({ status: 'SEM_DADOS', inicio, fim });
const r2 = v => Math.round(v * 100) / 100;
const dias = (a, b) => Math.round((Date.parse(b) - Date.parse(a)) / 86400000);
const medir = lista => {
  const noPrazo = lista.filter(p => p.enviado <= p.prometido).length;
  return { pedidos_enviados: lista.length, prazo_medio_dias: r2(lista.reduce((s, p) => s + dias(p.data, p.enviado), 0) / lista.length), no_prazo: noPrazo, atrasados: lista.length - noPrazo, no_prazo_pct: r2(noPrazo / lista.length * 100), frete_medio: r2(lista.reduce((s, p) => s + p.frete, 0) / lista.length) };
};
const grupos = {};
for (const p of enviados) (grupos[p.transportadora] = grupos[p.transportadora] || []).push(p);
const transportadoras = Object.entries(grupos).map(([nome, lista]) => ({ transportadora: nome, ...medir(lista) })).sort((a, b) => a.prazo_medio_dias - b.prazo_medio_dias);
return JSON.stringify({ status: 'OK', inicio, fim, geral: medir(enviados), transportadoras });

const d = $('Normaliza pedidos').first().json;
const p = d.pedidos.find(x => x.pedido === Number(query.numero));
if (!p) return JSON.stringify({ status: 'NAO_ENCONTRADO', numero: query.numero });
const r2 = v => Math.round(v * 100) / 100;
const situacao = p.enviado ? (p.enviado <= p.prometido ? 'enviado no prazo' : 'enviado com atraso') : (p.prometido < d.hoje ? 'em aberto e atrasado' : 'em aberto');
return JSON.stringify({ status: 'OK', pedido: p.pedido, cliente: p.cliente, situacao, data: p.data, prometido: p.prometido, enviado: p.enviado, transportadora: p.transportadora, destino: p.destino, frete: r2(p.frete), valor: r2(p.valor), itens: p.itens.map(i => ({ ...i, liquido: r2(i.liquido) })) });
